function E(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}function by(id){return document.getElementById(id)}function lang(x){x=String(x||'').toLowerCase();return x==='it'||x.indexOf('ital')===0?'it':x==='es'||x.indexOf('spa')===0||x.indexOf('esp')===0?'es':x==='en'||x.indexOf('eng')===0||x.indexOf('ing')===0?'en':'other'}function label(k){return (L.find(function(x){return x[0]===k})||L[3])[1]}function fmt(d){if(!d)return 'Fecha por confirmar';var v=new Date(d);return isNaN(v.getTime())?'Fecha por confirmar':v.toLocaleString('es-ES',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'})}function notify(m){var t=by('toast');t.textContent=m;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(function(){t.classList.remove('show')},4200)}function safe(u){try{var x=new URL(u,location.origin);return x.protocol==='https:'||x.origin===location.origin?x.href:'#'}catch(e){return '#'}}function authHeaders(json){var h={'apikey':C.key};if(S.token)h.Authorization='Bearer '+S.token;if(json)h['Content-Type']='application/json';return h}function req(table,query,method,body){if(!connected)return Promise.resolve([]);return fetch(C.url.replace(/\/$/,'')+'/rest/v1/'+table+(query||''),{method:method||'GET',cache:'no-store',headers:Object.assign(authHeaders(body!==undefined),{'Prefer':'return=representation'}),body:body===undefined?undefined:JSON.stringify(body)}).then(async function(r){var x=await r.text();if(!r.ok)throw Error(x.slice(0,280)||r.status);return x?JSON.parse(x):[]})}function count(k){return S.scores.filter(function(s){return s.language===k}).length}function nav(){by('sidenav').innerHTML=P.map(function(x){return '<button class="nav-btn '+(S.page===x[0]?'active':'')+'" data-page="'+x[0]+'"><span class="ni">'+x[2]+'</span>'+x[1]+'</button>'}).join('');by('mobileNav').innerHTML=P.filter(function(x){return ['inicio','repertorio','estudio','roma','mas'].indexOf(x[0])>=0}).map(function(x){return '<button class="'+(S.page===x[0]?'active':'')+'" data-page="'+x[0]+'"><span class="ni">'+x[2]+'</span>'+x[1]+'</button>'}).join('');by('currentTitle').textContent=(P.find(function(x){return x[0]===S.page})||P[0])[1];by('mode').textContent=!navigator.onLine?'Sin conexión · copia local':S.syncState==='available'?'Sincronizado':S.syncState==='stale'?'Datos guardados · sin actualizar':'Conectando…'}function section(title,page){return '<div class="sec-head"><h2>'+title+'</h2><button class="link" data-page="'+page+'">Ver todo →</button></div>'}function empty(ico,title,txt){return '<div class="empty"><div class="symbol">'+ico+'</div><strong>'+title+'</strong><p>'+txt+'</p></div>'}function pageHead(t,sub,action){return '<div class="heading"><div><div class="eyebrow">CORO ITALIANO</div><h1>'+E(t)+'</h1><p>'+E(sub)+'</p></div>'+(action||'')+'</div>'}
function homeScoreOrder(a){return a.filter(function(x){return x.published!==false&&x.created_at&&!isNaN(Date.parse(x.created_at))}).sort(function(a,b){return Date.parse(b.created_at)-Date.parse(a.created_at)||String(a.title).localeCompare(String(b.title),'es')})}
function homeDate(d){return new Date(d).toLocaleDateString('es-ES',{day:'numeric',month:'short'})}
function homeIcon(k){var paths={book:'<path d="M4 19V5a2 2 0 0 1 2-2h14v16H6a2 2 0 0 0 0 4h14"/><path d="M8 7h8m-8 4h6"/>',study:'<path d="M9 18V5l11-2v13"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',list:'<path d="M9 6h11M9 12h11M9 18h11M4 6h.01M4 12h.01M4 18h.01"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="m8 12 3 3 5-6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>'};return '<svg aria-hidden="true" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'+(paths[k]||paths.arrow)+'</svg>'}
