function visibleScores(){
 var hasQuery=!!CoroSearch.normalize(S.query),a=S.scores.filter(function(x){return S.lang==='all'||x.language===S.lang});
 if(hasQuery){
  a=a.map(function(s){return {score:s,relevance:CoroSearch.rank(S.query,s.title,[s.origin_id,s.topic,s.voice_part,s.composer])}})
   .filter(function(x){return isFinite(x.relevance)})
   .sort(function(x,y){return x.relevance-y.relevance||x.score.title.localeCompare(y.score.title,'es')})
   .map(function(x){return x.score});
 }
 if(S.tab==='added')return hasQuery?a.filter(function(x){return x.published!==false&&x.created_at&&!isNaN(Date.parse(x.created_at))}):homeScoreOrder(a);
 if(S.tab==='recent'){var order={};S.recent.forEach(function(x,i){order[x.score_id]=i});var recents=a.filter(function(x){return order[x.id]!=null});return hasQuery?recents:recents.sort(function(x,y){return order[x.id]-order[y.id]})}
 if(S.tab==='favorites')return a.filter(function(x){return S.favorites.includes(x.id)});
 if(S.tab==='downloaded')return a.filter(function(x){return S.downloadedIds.includes(x.id)});
 return hasQuery?a:a.sort(function(x,y){return x.title.localeCompare(y.title,'es')});
}
function repertorio(){var filtered=visibleScores();return pageHead('Biblioteca de partituras','Busca por título, número, idioma o temática. La app prepara automáticamente las partituras para ensayar sin internet.','<div class="controls">'+(S.admin?'<button class="btn" data-modal="score">＋ Subir partitura</button>':'')+'</div>')+'<div class="search"><span>⌕</span><input id="searchScores" value="'+E(S.query)+'" type="search" placeholder="Busca títulos, números o palabras…" aria-label="Buscar partituras"><button type="button" class="link" data-action="clearSearch" aria-label="Limpiar búsqueda" title="Limpiar búsqueda">×</button></div><div class="filters">'+[['all','Todos'],['added','Últimos agregados'],['recent','Mi historial'],['favorites','Favoritos'],['downloaded','Sin conexión']].map(function(x){return '<button data-tab="'+x[0]+'" class="filter '+(S.tab===x[0]?'active':'')+'">'+x[1]+'</button>'}).join('')+(S.tab==='recent'?'<button class="link" data-action="clearRecent">Borrar mi historial</button>':'')+'</div><div class="filters">'+[['all','Todos los idiomas']].concat(L.map(function(x){return[x[0],x[1]]})).map(function(x){return '<button class="filter '+(S.lang===x[0]?'active':'')+'" data-lang="'+x[0]+'">'+x[1]+' · '+(x[0]==='all'?S.scores.length:count(x[0]))+'</button>'}).join('')+'</div><div id="results"><p class="eyebrow">'+filtered.length+' RESULTADOS</p>'+(filtered.length?'<div class="song-list">'+filtered.slice(0,S.displayLimit).map(songRow).join('')+'</div>'+(filtered.length>S.displayLimit?'<div style="padding:15px;text-align:center"><button class="btn white" data-action="moreScores">Mostrar más · '+(filtered.length-S.displayLimit)+' restantes</button></div>':''):empty('♫','Sin coincidencias',S.query?'Prueba con otra palabra, menos texto o revisa los filtros de idioma.':'Todavía no hay partituras con los filtros seleccionados.'))+'</div>'}

