function listCard(p){var n=S.items.filter(function(x){return x.playlist_id===p.id}).length;return '<div class="item"><div><div class="controls">'+(p.is_pinned?'<span class="badge pin">⌖ Fijada</span>':'')+'<span class="badge green">'+n+' partituras</span></div><h3>'+E(p.title)+'</h3><p>'+E(p.description||'Colección de partituras del coro')+'</p></div><div class="controls"><button class="btn white sm" data-openlist="'+E(p.id)+'">Abrir lista</button>'+(S.admin?'<button class="btn white sm" data-editlist="'+E(p.id)+'">Editar</button>':'')+'</div></div>'}
