function playlistDetail(id,restoring){var p=S.playlists.find(function(x){return x.id===id});if(!p){notify('No se encuentra la lista');return}if(!restoring){routeSave();S.page='listadetail';routeList=id;routePush(null)}else{S.page='listadetail';routeList=id}backButton();by('currentTitle').textContent='Lista de cantos';var its=S.items.filter(function(x){return x.playlist_id===id}).sort(function(a,b){return a.position-b.position});by('screen').innerHTML=pageHead(p.title,p.description||'Lista de partituras','<div class="controls"><button class="btn white" data-page="listas">← Volver</button></div>')+(its.length?'<div class="song-list">'+its.map(function(x){var s=S.scores.find(function(y){return y.id===x.score_id});return s?songRow(s):''}).join('')+'</div>':empty('♫','Lista sin partituras','Esta lista todavía no contiene cantos.'))}
