function renderContent(type){var info={eventos:['Agenda del coro','Ensayos, reuniones y presentaciones','events','starts_at'],avisos:['Comunicados','Avisos importantes para todos los integrantes','announcements','created_at'],uniformes:['Uniformes','Indicaciones de vestimenta para cada actividad','uniforms','event_at'],incidencias:['Registro de incidencias','Seguimiento de asuntos y necesidades del coro','incidents','created_at']},x=info[type],rows=S[x[2]],extra=(S.admin||(type==='incidencias'&&S.token))?'<button class="btn" data-modal="'+x[2]+'">＋ Nuevo registro</button>':'';if(type==='incidencias'&&!S.admin){rows=S.incidents}if(type==='incidencias'&&S.userId){rows=S.pending.map(function(x){return {category:x.body.category,description:x.body.description,status:'pendiente de sincronizar',created_at:new Date(x.saved_at).toISOString(),_pending:true}}).concat(rows)}return pageHead(x[0],x[1],extra)+(type==='incidencias'?'<div class="notice">Las incidencias pueden incluir asistencia, material, partituras, logística, uniformes, sonido y otros asuntos. Cada integrante puede ver sus propios reportes; el administrador tiene acceso al seguimiento general.</div>':'')+(rows.length?'<div class="stack">'+rows.map(function(r){var desc=r.description||r.body||r.instructions||r.category||'',date=r.starts_at||r.event_at||r.created_at;return itemCard(r.title||r.category||'Incidencia',desc+(date?' · '+fmt(date):''),'<span class="badge '+(r.status==='open'?'red':'green')+'">'+E(r.status||'Publicado')+'</span>',S.admin?'<button class="btn white sm" data-edit="'+E(x[2])+':'+E(r.id)+'">Editar</button>':'')}).join('')+'</div>':empty('◌','Sin información publicada','Los nuevos registros aparecerán aquí cuando sean creados por la administración.'))}
