function render(){nav();backButton();if(S.page==='listadetail'&&routeList){if(S.playlists.some(function(x){return x.id===routeList})){playlistDetail(routeList,true);if(window.CoroAuto)syncLibrary();return}S.page='listas';routeList=null;}var f={inicio:home,repertorio:repertorio,listas:lists,mas:more,configuracion:settingsPage,estudio:CoroStudy.renderStudy,roma:CoroStudy.renderRoma,eventos:function(){return renderContent('eventos')},avisos:function(){return renderContent('avisos')},uniformes:function(){return renderContent('uniformes')},incidencias:function(){return renderContent('incidencias')},admin:admin};by('screen').innerHTML=(f[S.page]||home)();if(window.CoroAuto)syncLibrary()}
var routeList=null,routeRestoring=false,readerEpoch=0,routeBusy=false;
