async function authSignup(e){e.preventDefault();var fd=new FormData(e.target),password=fd.get('password');if(password!==fd.get('confirm')){notify('Las contraseñas no coinciden');return}if(password.length<12){notify('Utiliza al menos 12 caracteres');return}try{var r=await fetch(C.url.replace(/\/$/,'')+'/auth/v1/signup',{method:'POST',headers:{apikey:C.key,'Content-Type':'application/json'},body:JSON.stringify({email:fd.get('email'),password:password})});var d=await r.json();if(!r.ok)throw Error(d.msg||d.error_description||d.message||'No se pudo crear la cuenta');S.accountMode='login';notify('Registro recibido. Revisa tu correo para verificar tu cuenta si se solicita.');render()}catch(err){notify('Registro: '+err.message)}}
