async function login(e){e.preventDefault();if(!connected)return;var fd=new FormData(e.target);try{var r=await fetch(C.url.replace(/\/$/,'')+'/auth/v1/token?grant_type=password',{method:'POST',headers:{'apikey':C.key,'Content-Type':'application/json'},body:JSON.stringify({email:fd.get('email'),password:fd.get('password')})});var a=await r.json();if(!r.ok||!a.access_token)throw Error(a.msg||a.error_description||'Datos incorrectos');S.token=a.access_token;S.refreshToken=a.refresh_token;sessionStorage.setItem('choir-token',S.token);sessionStorage.setItem('choir-refresh',S.refreshToken);decodeUser();S.accountMode='profile';await loadProfile();await loadLocal();await loadRemote();await CoroStudy.load();await loadRegister();await syncPending();await syncFavorites();notify('Sesión iniciada');render()}catch(err){notify(err.message)}}function decodeUser(){try{var p=JSON.parse(atob(S.token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));S.admin=!!(p.app_metadata&&p.app_metadata.choir_role==='admin');S.email=p.email||'';S.userId=p.sub||''}catch(e){S.token='';S.admin=false}}async function refreshSession(){if(!connected||!S.refreshToken||!navigator.onLine)return;try{var r=await fetch(C.url.replace(/\/$/,'')+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{'apikey':C.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:S.refreshToken})});if(!r.ok)throw Error('expirada');var a=await r.json();S.token=a.access_token;S.refreshToken=a.refresh_token;sessionStorage.setItem('choir-token',S.token);sessionStorage.setItem('choir-refresh',S.refreshToken);decodeUser()}catch(e){S.token='';S.admin=false;sessionStorage.removeItem('choir-token');sessionStorage.removeItem('choir-refresh')}}
