function localScope(){return S.userId?'user:'+S.userId:'visitor'}
async function loadLocal(){
 var scope=localScope();
 try{
  var essential=await Promise.allSettled([CoroOffline.list('recents'),CoroOffline.get('snapshots','public')]);
  if(scope!==localScope())return;
  if(essential[0].status==='fulfilled')S.recent=essential[0].value.filter(function(x){return x.scope===scope}).sort(function(a,b){return b.last_at-a.last_at}).slice(0,50);
  if(essential[1].status==='fulfilled'&&essential[1].value){var snapshot=essential[1].value;
   ['playlists','items','events','announcements','uniforms'].forEach(function(k){S[k]=snapshot[k]||[]});
   var map=new Map(S.scores.map(function(x){return[x.origin_id||x.id,x]}));
   (snapshot.scores||[]).forEach(function(x){map.set(x.origin_id||x.id,x)});
   S.scores=Array.from(map.values());S.syncState='stale'}
 }catch(e){console.warn('Lectura inicial local',e)}
 // El inventario de PDFs (hasta cientos de entradas) y los datos secundarios nunca bloquean Inicio.
 Promise.allSettled([CoroOffline.pdfKeys(),CoroOffline.list('favorites'),CoroOffline.list('pending')]).then(function(results){
  if(scope!==localScope())return;
  if(results[0].status==='fulfilled'){var known=new Set(results[0].value);S.downloadedIds=S.scores.filter(function(x){return known.has(x.pdfUrl)}).map(function(x){return x.id})}
  if(results[1].status==='fulfilled')S.favorites=results[1].value.filter(function(x){return x.scope===scope&&x.active}).map(function(x){return x.score_id});
  if(results[2].status==='fulfilled')S.pending=results[2].value.filter(function(x){return x.user_id===S.userId});
  safeSyncRender();
 }).catch(function(e){console.warn('Datos locales secundarios',e)})
}
async function persistPublic(){try{var published=S.playlists.filter(function(x){return x.is_published});var ids=new Set(published.map(function(x){return x.id}));await CoroOffline.put('snapshots',{key:'public',updated_at:Date.now(),scores:S.scores.filter(function(x){return x.published!==false}),playlists:published,items:S.items.filter(function(x){return ids.has(x.playlist_id)}),events:S.events.filter(function(x){return x.published}),announcements:S.announcements.filter(function(x){return x.published}),uniforms:S.uniforms.filter(function(x){return x.published})})}catch(e){console.warn('Error al guardar copia local',e)}}
async function recordRecent(){if(!S.doc||!S.reader)return;try{var now=Date.now(),scope=localScope(),v={key:scope+':'+S.reader.id,scope:scope,score_id:S.reader.id,last_at:now,page:S.pdfPage,zoom:S.pdfScale,rotation:S.pdfRotation};await CoroOffline.put('recents',v);S.recent=S.recent.filter(function(x){return x.score_id!==v.score_id});S.recent.unshift(v);S.recent=S.recent.slice(0,50);var all=await CoroOffline.list('recents');var old=all.filter(function(x){return x.scope===scope}).sort(function(a,b){return b.last_at-a.last_at}).slice(50);for(var entry of old)await CoroOffline.remove('recents',entry.key)}catch(e){console.warn('Historial',e)}}
