async function fetchPdfBytes(url){if(String(url).startsWith('blob:')){var r=await fetch(url);return await r.arrayBuffer()}return CoroAuto.read(url)}
function syncLibrary(){
 var priority=new Set(S.favorites.concat(S.recent.map(function(x){return x.score_id})).concat(S.items.map(function(x){return x.score_id}))),scores=S.scores.slice().sort(function(x,y){return Number(priority.has(y.id))-Number(priority.has(x.id))});
 CoroAuto.configure(scores,CoroStudy.offlineJobs?CoroStudy.offlineJobs(scores):[],function(urls){
  var set=new Set(urls);S.downloadedIds=S.scores.filter(function(x){try{return set.has(new URL(x.pdfUrl,location.origin).href)}catch(e){return false}}).map(function(x){return x.id});
  if(S.page==='repertorio'&&S.tab==='downloaded'&&!S.reader&&by('results')){var t=document.createElement('div');t.innerHTML=repertorio();var r=t.querySelector('#results');if(r)by('results').innerHTML=r.innerHTML}
 })
}
