async function toggleFavorite(){if(!S.reader)return;var id=S.reader.id,active=!S.favorites.includes(id),v={key:localScope()+':'+id,scope:localScope(),score_id:id,active:active,dirty:!!S.userId};try{await CoroOffline.put('favorites',v);if(active)S.favorites.unshift(id);else S.favorites=S.favorites.filter(function(x){return x!==id});var btn=by('favoritePdf');if(btn){btn.textContent=active?'★ Favorito':'☆ Favorito';btn.title=active?'Quitar favorito':'Marcar favorito'}notify(active?'Partitura añadida a favoritos':'Partitura quitada de favoritos');if(S.userId&&navigator.onLine)syncFavorites()}catch(e){notify('No se pudo guardar favorito: '+e.message)}}
