 if(!by('readerRoot').children.length){routeSave();routePush('reader')}stopPdfReader();var epoch=++readerEpoch;S.reader=score;S.doc=null;S.noteTool='hand';S.pdfPage=1;S.pdfScale=1;S.pdfRotation=0;S.readerMode=localStorage.getItem('coroReaderMode')==='book'?'book':'continuous';
