  window.pdfjsLib.GlobalWorkerOptions.workerSrc='/ios12/vendor/pdf.worker.min.js';var bytes=opened[1];
  if(epoch!==readerEpoch)return;var task=window.pdfjsLib.getDocument({data:new Uint8Array(bytes),isEvalSupported:false});var doc=await task.promise;if(epoch!==readerEpoch){doc.destroy();return}S.doc=doc;
